import os

def save_todos(todos):
    try:
        with open("todos.json", "w") as file:
            json.dump(todos, file)
    except (IOError, OSError) as e:
        # Handle file write errors (e.g., disk full, permission denied)
        raise RuntimeError(f"Failed to save todos: {e}")

def load_todos():
    try:
        if os.path.exists("todos.json"):
            with open("todos.json", "r") as file:
                return json.load(file)
        return []
    except (IOError, OSError, json.JSONDecodeError) as e:
        # Handle file read errors (e.g., permission denied, corrupted JSON)
        raise RuntimeError(f"Failed to load todos: {e}")"}
